button_details.script:
					function onButtonPress()
            local sDBnode = window.getDatabaseNode();
            sf.DebugOut("DB Node: " .. sDBnode.getPath());

            local sRuleset = Interface.getRuleset();
            sf.DebugOut("Using ruleset: " .. sRuleset, true);

            Interface.openWindow("charsheet_abilityboost_sfrpg", sDBnode);
					end

number_content_base.script:
					function onDoubleClick()
            -- add some logic for grenades: sync inventory uses/carried with weapon uses
            checkGrenade();

            -- then we call the outer reload action to do the normal behavior
            if WindowManager and WindowManager.callOuterWindowFunction then
              WindowManager.callOuterWindowFunction(window, "onReloadAction");
            end
          end

          -- grenade handling          
          function checkGrenade()
            -- determine subtype
            local sDBnode = window.getDatabaseNode();
            local sSubtype = DB.getValue(sDBnode, "subtype", "")
            sf.DebugOut("uses:onDoubleClick subtype=" .. tostring(sSubtype));

            if not (sSubtype == "grenade" or sSubtype == "Grenade") then
              -- not a grenade, return so it can continue as before
              return;
            end

            -- grenade: find linked inventory node using the windowreference value (class, recordname)
            local sShortcutClass, sRecordName = DB.getValue(sDBnode, "shortcut")
            sf.DebugOut("uses:onDoubleClick shortcut class=" .. tostring(sShortcutClass) .. ", recordname=" .. tostring(sRecordName))
            local nodeInv = nil
            if sRecordName and sRecordName ~= "" then
              nodeInv = DB.findNode(sRecordName);
            end

            -- give up if no linked inventory found
            if not nodeInv then
              sf.ErrorOut("uses:onDoubleClick: no linked inventory found");
              return;
            end

            -- get inventory count from linked inventory item "count" element
            local nInvCount = DB.getValue(nodeInv, "count", 0);
            local nInvUses = DB.getValue(nodeInv, "uses", 0)
            sf.DebugOut("linked inventory count=" .. tostring(nInvCount) .. ", uses=" .. tostring(nInvUses));

            -- get the "ammo" count to determine how many grenades were used
            local nAmmo = DB.getValue(sDBnode, "ammo", 0)
            sf.DebugOut("uses:onDoubleClick current used ammo=" .. tostring(nAmmo) .. ", invCount=" .. tostring(nInvCount))
            
            -- determine the adjust new inventory count and set it in both places (uses and inventorylist count)
            local nToConsume = tonumber(nAmmo) or 0
            local nNewInv = math.max(nInvCount - nToConsume, 0)
            Debug.console("uses:onDoubleClick consuming " .. tostring(nToConsume) .. ", newInv=" .. tostring(nNewInv))

            -- now set the adjusted inventory counts
            DB.setValue(nodeInv, "count", "number", nNewInv);
            DB.setValue(sDBnode, "uses", "number", nNewInv);
            Debug.console("uses:onDoubleClick set inventory count and weapon uses to " .. tostring(nNewInv));
					end
